  'g3.loaded': '{d} ꯗ ꯁꯦꯚ ꯇꯧꯔꯕ ꯅꯍꯥꯛꯀꯤ ꯍꯤꯁꯥꯕ ꯎꯠꯂꯤ꯫ ꯑꯅꯧꯕꯥ ꯇꯧꯗꯨꯅ ꯍꯧꯅꯕꯥ “ꯁꯦꯚ ꯇꯧꯔꯕ ꯕꯤꯜꯁꯤꯡꯗꯒꯤ ꯑꯃꯨꯛ ꯊꯝꯕꯤꯌꯨ” ꯄ꯭ꯔꯦꯁ ꯇꯧꯕꯤꯌꯨ꯫',
  'g3.formh': 'ꯅꯍꯥꯛꯀꯤ ꯁꯦꯚ ꯇꯧꯔꯕ ꯕꯤꯜꯁꯤꯡꯒꯤ ꯃꯁꯤꯡꯁꯤꯡ ꯊꯃꯖꯤꯟꯂꯦ꯫ ꯕꯣꯛꯁ ꯑꯃꯃꯛꯇ ꯅꯍꯥꯛꯅ ꯇꯥꯏꯞ ꯇꯧꯕ ꯌꯥꯏ, ꯑꯦꯛꯁꯦꯝꯄꯜ ꯑꯣꯏꯅ ꯅꯍꯥꯛꯀꯤ GSTR-2B ꯗ ꯎꯠꯂꯤꯕ ITC꯫ ꯅꯍꯥꯛꯅ ꯍꯣꯡꯗꯣꯛꯈꯤꯕ ꯕꯣꯛꯁꯁꯤꯡ ꯑꯗꯨ ꯃꯈꯥ ꯇꯥꯅ ꯎꯠꯀꯅꯤ꯫',
