  "b2.farule1": "ꯑꯦꯀꯥꯎꯟꯠꯀꯤ ꯗꯦꯞꯔꯤꯁꯤꯌꯦꯁꯟ ꯀꯝꯄꯦꯅꯤꯖ ꯑꯦꯛꯠ, 2013 ꯒꯤ ꯁꯦꯗ꯭ꯌꯨꯜ II ꯃꯇꯨꯡ ꯏꯟꯅꯥ: ꯑꯦꯁꯦꯠꯀꯤ ꯃꯈꯜ ꯈꯨꯗꯤꯡꯃꯛꯀꯤ ꯁꯤꯖꯤꯟꯅꯕꯥ ꯌꯥꯕꯥ ꯃꯇꯝ ꯂꯩ (ꯈꯨꯗꯝ ꯑꯣꯏꯅꯥ ꯀꯝꯄꯨꯇꯔ ꯆꯍꯤ 3, ꯐꯔꯅꯤꯆꯔ ꯆꯍꯤ 10, ꯄ꯭ꯂꯥꯟꯠ ꯑꯃꯁꯨꯡ ꯃꯦꯁꯤꯅꯔꯤ ꯆꯍꯤ 15, ꯀꯥꯔ ꯆꯍꯤ 8), ꯂꯦꯃꯍꯧꯔꯤꯕꯥ ꯚꯦꯜꯌꯨ ꯃꯇꯝ ꯄꯨꯝꯅꯃꯛꯇꯥ ꯃꯃꯂꯒꯤ 5% ꯗꯒꯤ ꯍꯦꯜꯂꯣꯏ, ꯑꯃꯁꯨꯡ ꯆꯍꯤꯒꯤ ꯃꯔꯛꯇꯥ ꯍꯥꯄꯆꯤꯟꯈꯤꯕꯥ ꯅꯠꯔꯒꯥ ꯌꯣꯟꯈꯤꯕꯥ ꯑꯦꯁꯦꯠꯇꯥ ꯁꯤꯖꯤꯟꯅꯈꯤꯕꯥ ꯅꯨꯃꯤꯠꯁꯤꯡꯒꯤ ꯗꯦꯞꯔꯤꯁꯤꯌꯦꯁꯟ ꯈꯛ ꯂꯩ। ꯁ꯭ꯠꯔꯦꯠ ꯂꯥꯏꯟ (SLM: ꯆꯍꯤ ꯈꯨꯗꯤꯡꯗꯥ ꯃꯥꯟꯅꯕꯥ ꯁꯦꯟ) ꯅꯠꯔꯒꯥ ꯔꯤꯇꯟ ꯗꯥꯎꯟ ꯚꯦꯜꯌꯨ (WDV: ꯂꯦꯃꯍꯧꯔꯤꯕꯥ ꯁꯦꯟꯗꯥ ꯂꯦꯞꯄꯥ ꯔꯦꯠ) ꯈꯅꯕꯤꯌꯨ। ꯄ꯭ꯔꯣꯄ꯭ꯔꯥꯏꯇꯔ ꯑꯃꯁꯨꯡ ꯐꯥꯔꯃꯁꯤꯡꯅꯥ ꯌꯥꯃꯗ꯭ꯔꯕꯗꯥ ꯃꯑꯣꯡ ꯑꯁꯤꯃꯛ ꯁꯤꯖꯤꯟꯅꯩ; ꯋꯥꯔꯦꯞ ꯑꯗꯨ ꯅꯍꯥꯛꯀꯤ ꯑꯦꯀꯥꯎꯟꯇꯦꯟꯇꯅꯥ ꯂꯧꯏ।",
  "b2.farule2": "ꯏꯟꯀꯝ ꯇꯦꯛꯁ ꯗꯦꯞꯔꯤꯁꯤꯌꯦꯁꯟ ꯕ꯭ꯂꯣꯛ ꯈꯨꯗꯤꯡꯃꯛꯀꯤ ꯇꯣꯉꯥꯟꯅꯥ ꯊꯤꯖꯤꯜꯂꯤ: ꯕ꯭ꯂꯣꯛ ꯔꯦꯠꯇꯥ ꯔꯤꯇꯟ ꯗꯥꯎꯟ ꯚꯦꯜꯌꯨ (ꯈꯨꯗꯝ ꯑꯣꯏꯅꯥ ꯄ꯭ꯂꯥꯟꯠ ꯑꯃꯁꯨꯡ ꯃꯦꯁꯤꯅꯔꯤ 15%, ꯐꯔꯅꯤꯆꯔ 10%, ꯀꯝꯄꯨꯇꯔ 40%), ꯆꯍꯤꯗꯥ ꯅꯨꯃꯤꯠ 180 ꯗꯒꯤ ꯍꯟꯊꯅꯥ ꯁꯤꯖꯤꯟꯅꯈꯤꯕꯥ ꯑꯦꯁꯦꯠꯇꯥ ꯔꯦꯠ ꯑꯔꯦꯛ ꯑꯍꯦꯟ, ꯑꯃꯁꯨꯡ ꯌꯣꯟꯕꯒꯤ ꯁꯦꯟ ꯕ꯭ꯂꯣꯛꯇꯒꯤ ꯍꯟꯊꯍꯜꯂꯤ। ꯃꯁꯤ ꯏꯟꯀꯝ ꯇꯦꯛꯁ ꯔꯤꯇꯔꯅꯒꯤꯗꯃꯛ ꯈꯛꯅꯤ, ꯑꯦꯀꯥꯎꯟꯠꯇꯥ ꯀꯩꯗꯧꯉꯩꯗꯁꯨ ꯊꯥꯗꯣꯛꯇꯦ। ꯊꯥꯗꯣꯀꯈꯤꯕꯥ ꯔꯦꯠꯁꯤꯡ ꯑꯁꯤ ꯃꯇꯝ ꯄꯨꯝꯅꯃꯛꯀꯤ ꯕ꯭ꯂꯣꯛ ꯔꯦꯠꯅꯤ: ꯅꯍꯥꯛꯀꯤ ꯑꯦꯀꯥꯎꯟꯇꯦꯟꯇꯒꯥ ꯌꯥꯝꯅꯥ ꯆꯦꯠꯅꯥ ꯍꯪꯕꯤꯌꯨ, ꯃꯔꯨ ꯑꯣꯏꯅꯥ 1 ꯑꯦꯞꯔꯤꯜ 2026 ꯗꯒꯤ ꯏꯟꯀꯝ-ꯇꯦꯛꯁ ꯑꯦꯛꯠ, 2025 ꯒꯤ ꯃꯈꯥꯗꯥ ꯂꯩꯕꯥ ꯆꯍꯤꯁꯤꯡꯒꯤꯗꯃꯛ।",
  "b2.farule3": "ꯅꯍꯥꯛꯅꯥ 'ꯗꯦꯞꯔꯤꯁꯤꯌꯦꯁꯟ ꯊꯥꯗꯣꯛꯎ' ꯅꯝꯂꯕꯗꯥ ꯈꯛ ꯗꯦꯞꯔꯤꯁꯤꯌꯦꯁꯟ ꯑꯦꯀꯥꯎꯟꯠꯇꯥ ꯆꯠꯏ: ꯆꯍꯤꯒꯤ ꯑꯔꯣꯏꯕ ꯅꯨꯃꯤꯠ (ꯅꯠꯔꯒꯥ ꯆꯍꯤꯒꯤ ꯃꯔꯛꯇꯥ ꯉꯁꯤ) ꯒꯤ ꯖꯔꯅꯦꯜ ꯑꯦꯟꯠꯔꯤꯅꯥ ꯗꯦꯞꯔꯤꯁꯤꯌꯦꯁꯟ ꯗꯦꯕꯤꯠ ꯇꯧꯏ ꯑꯃꯁꯨꯡ ꯑꯦꯁꯦꯠ ꯈꯨꯗꯤꯡꯃꯛ ꯍꯟꯊꯍꯜꯂꯤ। ꯃꯇꯨꯡꯗꯥ ꯑꯦꯁꯦꯠ ꯍꯣꯡꯗꯣꯛꯂꯕꯗꯤ ꯍꯟꯅꯥ ꯊꯥꯗꯣꯛꯎ, ꯈꯦꯠꯅꯕꯥ ꯈꯛ ꯍꯥꯄꯆꯤꯟꯒꯅꯤ।",
